window.products.push({"id":953794,"name":"North Mountain Supply - NMS A4128-C - 1 White Plastic 1 Gallon Glass Wide-Mouth 110 CT Fermentation/Canning Jar With Lid (1, White Plastic Lid)","category":"homeandappliances","retail price":0.0,"sale price":null,"image":"https://m.media-amazon.com/images/I/61h2PVW0JgL._SL1500_.jpg","description":"North Mountain Supply 1 gallon glass Wide-mouth 110 CT fermentation/canning jar with white plastic lid. Great for bulk canning, fermenting, dry storage, cookies, candy and terrariums. Often used for pickles, pickled eggs, kombucha, and various bulk storage items. Glass to avoid absorption of flavors and leaching of chemicals - USDA certified food grade. Made in the USA! from North Mountain Supply! we that our products will arrive undamaged and free of defects - covered under our 30 day hassle free replacement !","images":["https://m.media-amazon.com/images/I/61h2PVW0JgL._SL1500_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"North Mountain Supply","source_asin":"B0783SJ3YF","category_path":"Home & Kitchen"},"sku":"BM-953794","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B0783SJ3YF","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B0783SJ3YF","price_pending":true,"merchant_ready":false});
